class _BuildModule(Protocol):
    """A per-build layout module: its build, the builds all its layouts fit, and its layouts."""

    @property
    def BUILD(self) -> str: ...

    @property
    def KNOWN_BUILDS(self) -> tuple[str, ...]: ...

    @property
    def LAYOUTS(self) -> tuple[LayoutEntry, ...]: ...


def _build_modules() -> tuple[_BuildModule, ...]:
    from fmsave._layouts import fm26_26_1_0, fm26_26_3_2, fm27_27_0_0, fm27_27_1_0

    return (fm26_26_3_2, fm26_26_1_0, fm27_27_0_0, fm27_27_1_0)


def registered_layouts() -> tuple[LayoutEntry, ...]:
    return tuple(entry for module in _build_modules() for entry in module.LAYOUTS)


def known_builds() -> frozenset[str]:
    """Builds whose saves every region's layout fits; other builds borrow layouts."""
    return frozenset(build for module in _build_modules() for build in module.KNOWN_BUILDS)


def registered_fm27_builds() -> tuple[str, ...]:
    """The FM27 builds whose layouts other FM27 builds can borrow."""
    return tuple(sorted(build for build in known_builds() if build.startswith("27.")))


def _layout_build(build: str) -> str:
    """The build whose layouts a save of `build` is read with: itself, or the one it shares."""
    for module in _build_modules():
        if build in module.KNOWN_BUILDS:
            return module.BUILD
    return build


def find_layout[LayoutT: Layout](
    layout_type: type[LayoutT], region: str, schema: int | None, build: str
) -> LayoutMatch[LayoutT]:
    """The layout for a region, by schema and build, then schema, then build, then fallback.

    A layout registered for the save's own build and schema wins. Failing that, a schema match
    counts only among builds every region's layout fits, so one build's override of a shared
    schema is never applied to another build's save.

    FM27 prefers the save's own build and schema, then a shared schema. When the schema
    differs, try a unique layout from the save's build or other registered FM27 builds.
    """
    candidates = [
        entry
        for entry in registered_layouts()
        if entry.region == region and isinstance(entry.layout, layout_type)
    ]
    if build.startswith("27."):
        return _find_fm27_layout(candidates, layout_type, region, schema, build)
    layout_build = _layout_build(build)
    # Only FM26 builds lend a layout to a save of another build by schema. An FM27 build
    # lends none, so a schema FM27 alone registers never reaches an FM26 save.
    full_builds = frozenset(
        known_build for known_build in known_builds() if not known_build.startswith("27.")
    )
    for entry in candidates:
        if (
            schema is not None
            and entry.schema == schema
            and entry.build == layout_build
            and isinstance(entry.layout, layout_type)
        ):
            return LayoutMatch(entry.layout, True, entry.build, entry.schema)
    for entry in candidates:
        if (
            schema is not None
            and entry.schema == schema
            and entry.build in full_builds
            and isinstance(entry.layout, layout_type)
        ):
            return LayoutMatch(entry.layout, True, entry.build, entry.schema)
    for entry in candidates:
        if entry.build == layout_build and isinstance(entry.layout, layout_type):
            return LayoutMatch(entry.layout, entry.schema is None, entry.build, entry.schema)
    for entry in candidates:
        if entry.build == FALLBACK_BUILD and isinstance(entry.layout, layout_type):
            return LayoutMatch(entry.layout, False, entry.build, entry.schema)
    raise LookupError(f"no {layout_type.__name__} registered for region {region!r}")


def _find_fm27_layout[LayoutT: Layout](
    candidates: list[LayoutEntry],
    layout_type: type[LayoutT],
    region: str,
    schema: int | None,
    build: str,
) -> LayoutMatch[LayoutT]:
    """Select a unique same-edition layout, warning before a cross-schema read."""
    from fmsave._errors import ISSUES_URL, UnknownBuildWarning, UnsupportedGameError

    lender_builds = registered_fm27_builds()
    lent = [
        entry
        for entry in candidates
        if entry.build in lender_builds and isinstance(entry.layout, layout_type)
    ]
    own = [entry for entry in candidates if entry.build == build]
    tiers = (
        [entry for entry in own if entry.schema == schema],
        [entry for entry in lent if entry.schema == schema],
        own,
        lent,
    )
    for tier in tiers:
        if not tier:
            continue
        first = tier[0]
        if any(entry.layout != first.layout for entry in tier):
            raise UnsupportedGameError(
                f"FM27: multiple {layout_type.__name__} layouts fit the build and schema "
                f"information for {region!r}, build {build}, schema {schema}. See {ISSUES_URL}"
            )
        if not isinstance(first.layout, layout_type):
            raise TypeError("layout registry returned an unexpected layout type")
        if schema is not None and first.schema != schema:
            warnings.warn(
                UnknownBuildWarning(
                    f"FM27 build {build}: trying {first.build}'s {region!r} layout at schema "
                    f"{first.schema} on save schema {schema}. Decoded fields are unverified."
                ),
                skip_file_prefixes=(os.path.dirname(os.path.dirname(__file__)) + os.sep,),
            )
        return LayoutMatch(
            first.layout, first.build == build and first.schema == schema, first.build, first.schema
        )
    raise UnsupportedGameError(
        f"FM27: no {layout_type.__name__} layout for {region!r}, build {build}, "
        f"schema {schema}. See {ISSUES_URL}"
    )

//! FM24 per-version field tables. Mirrors `fields::fm26`: each sub-module
//! owns one entity type's `FIELDS` const slice and this module collects them
//! into the `FM24` `ReleaseLayout`.
//!
//! FM24 has no `game_plugin.dll` — the game logic and every entity-array RVA
//! live in `fm.exe` itself (image base 0x140000000), so `gp_base` is the
//! fm.exe base on this version (see `GameVersion::module_name`).

mod club;
mod player;
mod stadium;
pub mod staff;

pub(crate) use club::CLUB_SUB_RECORDS;
pub(crate) use club::FIELDS as CLUB_FIELDS;
pub(crate) use player::FIELDS as PLAYER_FIELDS;
pub(crate) use player::PLAYER_SUB_RECORDS;
pub(crate) use stadium::FIELDS as STADIUM_FIELDS;
pub(crate) use staff::FIELDS as STAFF_FIELDS;
pub(crate) use staff::STAFF_SUB_RECORDS;

use crate::fields::{ModuleAddresses, RecordedBuild, ReleaseLayout};
use crate::game_version::{GameVersion, Storefront};

pub static FM24: ReleaseLayout = ReleaseLayout {
    player_fields: PLAYER_FIELDS,
    staff_fields: STAFF_FIELDS,
    club_fields: CLUB_FIELDS,
    stadium_fields: STADIUM_FIELDS,

    player_sub_records: PLAYER_SUB_RECORDS,
    staff_sub_records: STAFF_SUB_RECORDS,
    club_sub_records: CLUB_SUB_RECORDS,
    stadium_sub_records: &[],
    player_lists: Some(&player::FM24_PLAYER_LISTS),
    morale_labels: player::MORALE_LABELS,
    person_profile: None,

    player_struct_size: 0x3E8, // pool stride
    staff_struct_size: 0x268,  // pool stride
    club_read_size: 0x200,     // furthest mapped club field is +0x150; objects are 0x170 apart
    stadium_entity_stride: 0xB0,

    human_manager_shift: staff::HUMAN_MANAGER_SHIFT,
    manager_shifted_fields: staff::MANAGER_SHIFTED_FIELDS,
    player_person_offset: 0,
    player_coach_shift: 0,
    age_reference_year: 2023,
};

/// FM24 schema — mapped 2026-10-22 against a fresh save (3 Jul 2023).
///
/// RVAs are relative to the fm.exe base. Each `(data, end)` pair is a
/// std::vector of object pointers in fm.exe's writable data:
///
/// - players `0x642EDD0` — 83,426 entries, 99.8% carry the player vtable
///   (fm.exe+0x5A4E958); contains Harry Kane. The neighbouring 116,856-entry
///   pair at 0x642EDB8 points 0x28 into a different object type.
/// - staff `0x642EDE8` — 33,835 entries (staff vtable fm.exe+0x5A4C2E8),
///   human manager last. The 24,775-entry pair at 0x642EDF0 is a subset.
/// - clubs `0x642EF58` — 36,725 entries (club vtable fm.exe+0x5A51F38); the
///   36,498-entry pair at 0x642EF88 is a strict subset.
///
/// The stadium array root is not located; stadiums are reached per club via
/// the `home_stadium` sub-record, so `rva_stadium_base` stays 0.
pub static FM24_STEAM: RecordedBuild = RecordedBuild {
    version: GameVersion::Fm24,
    storefront: Storefront::Steam,
    layout: &FM24,
    schema_name: "FM24_STEAM",
    addresses: ModuleAddresses {
        rva_humans_data: 0x642EDD0,
        rva_humans_end: 0x642EDD8,
        rva_staff_data: 0x642EDE8,
        rva_staff_end: 0x642EDF0,
        rva_clubs_data: 0x642EF58,
        rva_clubs_end: 0x642EF60,
        rva_stadium_base: 0,
        // Current game date, static DateDayYear (day of year with flag bits above
        // bit 8, then the year). Found with `scan_arrays --date`: of two statics
        // reading Mon 3 Jul 2023 (raw 0x07E71AB8 at 09:00), only this one moved
        // with FM's clock, reading 185/2023 on Tue 4 Jul and 186/2023 on Wed
        // 5 Jul after one-day holidays (2026-11-09). fm.exe+0x642F458 kept 3 Jul
        // (the game start date).
        rva_current_date: 0x631D5BC,
        full_finance_vtable_rva: 0,
        player_coach_vtable_rva: 0,
        human_manager_vtable_rva: 0,
    },

    // Counts observed in the mapping save (used by scan_arrays.rs labels).
    fmrte_players: 83426,
    fmrte_staff: 33835,
    fmrte_clubs: 36725,
    fmrte_humans: 1,

    // FNV-1a-style hash (see `process::hash_dll_header`) of the first 64 KB
    // of fm.exe for the FM24 build this schema was verified against.
    fingerprint: 0xFB39_952A_2028_7907,
};

/// FM24 schema, Epic Games Store build (Windows, 24.4.2+2081827).
///
/// The Steam layout and addresses with the Epic `fm.exe` fingerprint.
/// Contributed evidence (array roots, player attributes, club transfer
/// budget, write and restore) and the fields that are only inherited from
/// Steam are in docs/fm24/memory-layout.md ("Epic build").
pub static FM24_EPIC: RecordedBuild = RecordedBuild {
    storefront: Storefront::Epic,
    schema_name: "FM24_EPIC",
    fingerprint: 0x8FA1_13DB_9DCD_8883,
    ..FM24_STEAM
};

