    transfer_value_editable: false,
    injuries_vec: 0x00,
    injury_size: 0x38,
    injury_type_ptr: 0x08,
    injury_type_name: 0x20,
    injury_start: 0x20,
    injury_full_days: 0x28,
    injury_light_days: 0x2A,
    absences_vec: 0x18,
    absence_size: 0x20,
    absence_kind: 0x05,
    absence_start: 0x10,
    absence_days: 0x16,
    absence_ban: 0x19,
    absence_holiday: 0x1F,
    absence_kinds: &[(0x19, "Suspension/ban"), (0x1F, "Holiday")],
    relations_ptr: 0x2F8,
