    entry = DirectoryEntry(
        name=name_bytes.decode("ascii"),
        extension=extension_bytes.decode("ascii"),
        frame_offset=FRAME_BASE + relative_offset,
        compressed_size=compressed_size,
        decompressed_size=decompressed_size,
